concepts.example:
pub fn square(side: i32) -> i32 {
    side * side
}

pub fn remaining(total: i32, used: i32) -> i32 {
    total - used
}

pub fn triple_score(score: i32) -> i32 {
    let multiplier = 3;
    score * multiplier
}

pub fn nonnegative(value: i32) -> i32 {
    if value < 0 {
        0
    } else {
        value
    }
}

pub fn double_then_reduce(start: i32) -> i32 {
    let mut score = start;
    score *= 2;
    score -= 3;
    score
}

pub fn halve_until_small(start: u32) -> u32 {
    let mut value = start;
    while value > 3 {
        value /= 2;
    }
    value
}

pub fn product_through(n: u32) -> u32 {
    let mut product = 1;
    for factor in 1..=n {
        product *= factor;
    }
    product
}
